package com.appblock.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

class AppBlockRepository(context:Context) {
    private val prefs=context.applicationContext.getSharedPreferences("app_block_store",Context.MODE_PRIVATE)
    private val schemaVersion=6
    private fun a(key:String)=runCatching{JSONArray(prefs.getString(key,"[]"))}.getOrDefault(JSONArray())
    private fun put(key:String,v:JSONArray){prefs.edit().putString(key,v.toString()).apply()}
    fun settings()=AppSettings(prefs.getBoolean("focusEnabled",true),runCatching{BlockMode.valueOf(prefs.getString("mode",BlockMode.FOCUS.name)!!)}.getOrDefault(BlockMode.FOCUS),prefs.getInt("dailyLimit",0),prefs.getBoolean("notifications",true),prefs.getBoolean("onboardingComplete",false),prefs.getBoolean("sound",true),prefs.getBoolean("vibration",true),prefs.getBoolean("darkMode",true),prefs.getBoolean("disclosureAccepted",false),prefs.getLong("protectedSessionUntil",0L),prefs.getBoolean("localOnlyData",true),prefs.getBoolean("allowTemporaryUnlock",true),prefs.getInt("breakMinutes",0),prefs.getString("timezoneId",java.util.TimeZone.getDefault().id)?:java.util.TimeZone.getDefault().id,prefs.getBoolean("clock24Hour",true),prefs.getLong("heartbeat",0L),prefs.getString("failureReason",null),prefs.getLong("sessionBreakUntil",0L))
    fun saveSettings(s:AppSettings){prefs.edit().putInt("schemaVersion",schemaVersion).putBoolean("focusEnabled",s.focusEnabled).putString("mode",s.mode.name).putInt("dailyLimit",s.dailyLimit).putBoolean("notifications",s.notifications).putBoolean("onboardingComplete",s.onboardingComplete).putBoolean("sound",s.soundEnabled).putBoolean("vibration",s.vibrationEnabled).putBoolean("darkMode",s.darkMode).putBoolean("disclosureAccepted",s.disclosureAccepted).putLong("protectedSessionUntil",s.protectedSessionUntil).putBoolean("localOnlyData",s.localOnlyData).putBoolean("allowTemporaryUnlock",s.allowTemporaryUnlock).putInt("breakMinutes",s.breakMinutes).putString("timezoneId",s.timezoneId).putBoolean("clock24Hour",s.clock24Hour).putLong("heartbeat",s.protectionHeartbeatAt).putString("failureReason",s.protectionFailureReason).putLong("sessionBreakUntil",s.sessionBreakUntil).apply()}
    fun heartbeat(ok:Boolean=true,reason:String?=null)=saveSettings(settings().copy(protectionHeartbeatAt=System.currentTimeMillis(),protectionFailureReason=if(ok)null else reason))
    fun blockedApps():List<BlockedApp>=(0 until a("blockedApps").length()).mapNotNull{runCatching{val o=a("blockedApps").getJSONObject(it);BlockedApp(o.getString("package"),o.getString("name"),o.optString("category"),o.optBoolean("blocked",true),o.optInt("limit",0),o.optBoolean("protectedAllowed",false))}.getOrNull()}
    fun saveBlockedApps(v:List<BlockedApp>){put("blockedApps",JSONArray(v.map{JSONObject().put("package",it.packageName).put("name",it.name).put("category",it.category).put("blocked",it.blocked).put("limit",it.dailyLimitMinutes).put("protectedAllowed",it.allowedDuringProtected)}))}
    fun blockLists():List<BlockList>=(0 until a("blockLists").length()).mapNotNull{runCatching{val o=a("blockLists").getJSONObject(it);BlockList(o.getLong("id"),o.getString("name"),csvSet(o.optString("packages")),csvSet(o.optString("websites")),o.optBoolean("enabled",true),o.optBoolean("always",false),o.optString("category","Custom"))}.getOrNull()}
    fun saveBlockLists(v:List<BlockList>){put("blockLists",JSONArray(v.map{JSONObject().put("id",it.id).put("name",it.name).put("packages",it.packageNames.joinToString(",")).put("websites",it.websites.joinToString(",")).put("enabled",it.enabled).put("always",it.alwaysActive).put("category",it.category)}))}
    fun websites():Set<String> = prefs.getStringSet("websites",emptySet())?:emptySet()
    fun saveWebsites(v:Set<String>)=prefs.edit().putStringSet("websites",v).apply()
    fun schedules():List<BlockSchedule>=(0 until a("schedules").length()).mapNotNull{runCatching{val o=a("schedules").getJSONObject(it);BlockSchedule(o.getLong("id"),o.getString("name"),csvSet(o.optString("days")).mapNotNull{d->d.toIntOrNull()}.toSet(),o.getInt("start"),o.getInt("end"),o.optBoolean("enabled",true),o.optString("date").ifBlank{null},csvSet(o.optString("lists")).mapNotNull{d->d.toLongOrNull()}.toSet(),o.optString("timezone",java.util.TimeZone.getDefault().id),o.optInt("break",0))}.getOrNull()}
    fun saveSchedules(v:List<BlockSchedule>){put("schedules",JSONArray(v.map{JSONObject().put("id",it.id).put("name",it.name).put("days",it.days.joinToString(",")).put("start",it.startMinutes).put("end",it.endMinutes).put("enabled",it.enabled).put("date",it.oneTimeDate?:"").put("lists",it.blockListIds.joinToString(",")).put("timezone",it.timezoneId).put("break",it.breakMinutes)}))}
    fun focusSessions():List<FocusSession>=(0 until a("sessions").length()).mapNotNull{runCatching{val o=a("sessions").getJSONObject(it);FocusSession(o.getLong("id"),o.getLong("started"),o.getInt("duration"),o.optBoolean("completed"),o.optInt("planned",0),o.optInt("breaks",0),o.optBoolean("interrupted",false))}.getOrNull()}
    fun saveFocusSessions(v:List<FocusSession>){put("sessions",JSONArray(v.map{JSONObject().put("id",it.id).put("started",it.startedAt).put("duration",it.durationMinutes).put("completed",it.completed).put("planned",it.plannedMinutes).put("breaks",it.breaksMinutes).put("interrupted",it.interrupted)}))}
    fun blockEvents():List<BlockEvent>=(0 until a("blockEvents").length()).mapNotNull{runCatching{val o=a("blockEvents").getJSONObject(it);BlockEvent(o.getLong("id"),o.getLong("timestamp"),o.getString("package"),o.getString("target"),BlockReason.valueOf(o.getString("reason")),o.optString("detail"))}.getOrNull()}.sortedByDescending{it.timestamp}
    fun addBlockEvent(e:BlockEvent){val v=(blockEvents()+e).take(1000);put("blockEvents",JSONArray(v.map{JSONObject().put("id",it.id).put("timestamp",it.timestamp).put("package",it.packageName).put("target",it.target).put("reason",it.reason.name).put("detail",it.detail)}))}
    fun unlocks():List<UnlockGrant>=(0 until a("unlocks").length()).mapNotNull{runCatching{val o=a("unlocks").getJSONObject(it);UnlockGrant(o.getString("package"),o.getLong("expires"),o.optString("reason"))}.getOrNull()}.filter{it.expiresAt>System.currentTimeMillis()}
    fun saveUnlocks(v:List<UnlockGrant>){put("unlocks",JSONArray(v.map{JSONObject().put("package",it.packageName).put("expires",it.expiresAt).put("reason",it.reason)}))}
    fun goals()=GoalSettings(prefs.getInt("goalDaily",60),prefs.getInt("goalWeekly",300),prefs.getBoolean("goalEnabled",true))
    fun saveGoals(g:GoalSettings)=prefs.edit().putInt("goalDaily",g.dailyFocusMinutes).putInt("goalWeekly",g.weeklyFocusMinutes).putBoolean("goalEnabled",g.enabled).apply()
    fun temporaryUnlockUntil()=prefs.getLong("temporaryUnlockUntil",0L)
    fun saveTemporaryUnlockUntil(v:Long)=prefs.edit().putLong("temporaryUnlockUntil",v).apply()
    fun clearAll(){prefs.edit().clear().apply()}
    fun exportJson():String=JSONObject().apply{put("schemaVersion",schemaVersion);put("settings",settingsJson());put("blockedApps",JSONArray(blockedApps().map{appJson(it)}));put("blockLists",JSONArray(blockLists().map{listJson(it)}));put("websites",JSONArray(websites().toList()));put("schedules",JSONArray(schedules().map{scheduleJson(it)}));put("sessions",JSONArray(focusSessions().map{sessionJson(it)}));put("blockEvents",JSONArray(blockEvents().map{eventJson(it)}));put("unlocks",JSONArray(unlocks().map{unlockJson(it)}));put("goals",JSONObject().put("daily",goals().dailyFocusMinutes).put("weekly",goals().weeklyFocusMinutes).put("enabled",goals().enabled))}.toString(2)
    fun importJson(raw:String){val r=JSONObject(raw);r.optJSONObject("settings")?.let{saveSettings(parseSettings(it))};r.optJSONArray("blockedApps")?.let{saveBlockedApps((0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);BlockedApp(o.getString("package"),o.getString("name"),o.optString("category"),o.optBoolean("blocked",true),o.optInt("limit",0),o.optBoolean("protectedAllowed",false))}.getOrNull()})};r.optJSONArray("blockLists")?.let{saveBlockLists((0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);BlockList(o.getLong("id"),o.getString("name"),csvSet(o.optString("packages")),csvSet(o.optString("websites")),o.optBoolean("enabled",true),o.optBoolean("always",false),o.optString("category","Custom"))}.getOrNull()})};r.optJSONArray("websites")?.let{arr->saveWebsites((0 until arr.length()).map{n->arr.getString(n)}.toSet())};r.optJSONArray("schedules")?.let{saveSchedules((0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);BlockSchedule(o.getLong("id"),o.getString("name"),csvSet(o.optString("days")).mapNotNull(String::toIntOrNull).toSet(),o.getInt("start"),o.getInt("end"),o.optBoolean("enabled",true),o.optString("date").ifBlank{null},csvSet(o.optString("lists")).mapNotNull(String::toLongOrNull).toSet(),o.optString("timezone",java.util.TimeZone.getDefault().id),o.optInt("break",0))}.getOrNull()})};r.optJSONArray("sessions")?.let{saveFocusSessions((0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);FocusSession(o.getLong("id"),o.getLong("started"),o.getInt("duration"),o.optBoolean("completed"),o.optInt("planned",0),o.optInt("breaks",0),o.optBoolean("interrupted",false))}.getOrNull()})};r.optJSONArray("blockEvents")?.let{val v=(0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);BlockEvent(o.getLong("id"),o.getLong("timestamp"),o.getString("package"),o.getString("target"),BlockReason.valueOf(o.getString("reason")),o.optString("detail"))}.getOrNull()};put("blockEvents",JSONArray(v.map{eventJson(it)}))};r.optJSONArray("unlocks")?.let{saveUnlocks((0 until it.length()).mapNotNull{n->runCatching{val o=it.getJSONObject(n);UnlockGrant(o.getString("package"),o.getLong("expires"),o.optString("reason"))}.getOrNull()})};r.optJSONObject("goals")?.let{saveGoals(GoalSettings(it.optInt("daily",60),it.optInt("weekly",300),it.optBoolean("enabled",true)))}}
    private fun settingsJson()=settings().let{s->JSONObject().put("focusEnabled",s.focusEnabled).put("mode",s.mode.name).put("dailyLimit",s.dailyLimit).put("notifications",s.notifications).put("onboardingComplete",s.onboardingComplete).put("sound",s.soundEnabled).put("vibration",s.vibrationEnabled).put("darkMode",s.darkMode).put("disclosureAccepted",s.disclosureAccepted).put("protectedSessionUntil",s.protectedSessionUntil).put("localOnlyData",s.localOnlyData).put("allowTemporaryUnlock",s.allowTemporaryUnlock).put("breakMinutes",s.breakMinutes).put("timezoneId",s.timezoneId).put("clock24Hour",s.clock24Hour).put("sessionBreakUntil",s.sessionBreakUntil)}
    private fun parseSettings(o:JSONObject)=AppSettings(o.optBoolean("focusEnabled",true),runCatching{BlockMode.valueOf(o.optString("mode",BlockMode.FOCUS.name))}.getOrDefault(BlockMode.FOCUS),o.optInt("dailyLimit",0),o.optBoolean("notifications",true),o.optBoolean("onboardingComplete",true),o.optBoolean("sound",true),o.optBoolean("vibration",true),o.optBoolean("darkMode",true),o.optBoolean("disclosureAccepted",true),o.optLong("protectedSessionUntil",0),o.optBoolean("localOnlyData",true),o.optBoolean("allowTemporaryUnlock",true),o.optInt("breakMinutes",0),o.optString("timezoneId",java.util.TimeZone.getDefault().id),o.optBoolean("clock24Hour",true),0L,null,o.optLong("sessionBreakUntil",0L))
    private fun appJson(v:BlockedApp)=JSONObject().put("package",v.packageName).put("name",v.name).put("category",v.category).put("blocked",v.blocked).put("limit",v.dailyLimitMinutes).put("protectedAllowed",v.allowedDuringProtected)
    private fun listJson(v:BlockList)=JSONObject().put("id",v.id).put("name",v.name).put("packages",v.packageNames.joinToString(",")).put("websites",v.websites.joinToString(",")).put("enabled",v.enabled).put("always",v.alwaysActive).put("category",v.category)
    private fun scheduleJson(v:BlockSchedule)=JSONObject().put("id",v.id).put("name",v.name).put("days",v.days.joinToString(",")).put("start",v.startMinutes).put("end",v.endMinutes).put("enabled",v.enabled).put("date",v.oneTimeDate?:"").put("lists",v.blockListIds.joinToString(",")).put("timezone",v.timezoneId).put("break",v.breakMinutes)
    private fun sessionJson(v:FocusSession)=JSONObject().put("id",v.id).put("started",v.startedAt).put("duration",v.durationMinutes).put("completed",v.completed).put("planned",v.plannedMinutes).put("breaks",v.breaksMinutes).put("interrupted",v.interrupted)
    private fun eventJson(v:BlockEvent)=JSONObject().put("id",v.id).put("timestamp",v.timestamp).put("package",v.packageName).put("target",v.target).put("reason",v.reason.name).put("detail",v.detail)
    private fun unlockJson(v:UnlockGrant)=JSONObject().put("package",v.packageName).put("expires",v.expiresAt).put("reason",v.reason)
    private fun csvSet(v:String)=v.split(',').filter(String::isNotBlank).toSet()
}